const raw = String(tools.read({path:'commits.jsonl'})).split('\n').map(l=>l.replace(/^\s*\d+\t/,'')).filter(l=>l.trim());
const rows = raw.map(l=>JSON.parse(l));
const mask = s => s.replace(/[0-9a-f]{7,}/g,'H');
// exact Fixes lines incl whitespace anomalies
const exact={}, anom=[];
for (const r of rows) for (const line of r.message.split('\n').slice(1)) {
  if (/fixes|Fixes|FIXES/.test(line)) { const k = mask(line.replace(/\d+/g,'N')); exact[k]=(exact[k]||0)+1; if(!/^Fixes #\d+$/.test(line)) anom.push(JSON.stringify(mask(line))); }
}
print('EXACTLIKE', JSON.stringify(exact));
print('NONEXACT', JSON.stringify([...new Set(anom)]));
// co-author lines raw (emails masked to length)
const co=[];
for (const r of rows) for (const line of r.message.split('\n').slice(1)) if (/^Co-authored-by/i.test(line)) co.push(mask(line));
print('CO raw sample', JSON.stringify([...new Set(co)]));
// multi coauthor commits
let multi=0; for (const r of rows){const c=r.message.split('\n').filter(l=>/^Co-authored-by/.test(l)); if(c.length>1) multi++;}
print('multi-coauthor commits', multi);
// reverts resolution
const revs = rows.filter(r=>r.message.split('\n')[0].startsWith('Revert "'));
const byHash = new Map(rows.map(r=>[r.hash,r]));
for (const rv of revs) {
  const line = rv.message.split('\n').find(l=>l.startsWith('This reverts commit '));
  const h = line ? line.replace('This reverts commit ','').replace(/\.$/,'').trim() : null;
  const t = byHash.get(h);
  print('revert names ->', h? 'FOUND':'MISSING', t? mask(t.message.split('\n')[0]) : '-', t? t.author : '-');
}
print('revert authors', JSON.stringify(revs.map(r=>r.author)));

