const mm=new Map(); for(const line of String(tools.read({path:'.mailmap'})).split('\n').map(l=>l.replace(/^\s*\d+\t/,'')).filter(l=>l.trim()&&!l.startsWith('#'))){const m=/^(.+?) <([^>]+)>(?: <([^>]+)>)?$/.exec(line.trim()); mm.set(m[3]||m[2],m[1].trim());}
const canon=(n,e)=>mm.get(e)||n;
const H=m=>m.split('\n')[0], re=/^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (.+)$/;
const named=new Set(); for(const r of rows){if(!H(r.message).startsWith('Revert "'))continue;const l=r.message.split('\n').find(x=>x.startsWith('This reverts commit '));if(l)named.add(l.replace('This reverts commit ','').replace(/\.$/,''));}
const sections={br:[],feat:[],fix:[]}, included=[];
for(const r of rows){const head=H(r.message); if(head.startsWith('Revert "')||named.has(r.hash))continue; const m=re.exec(head); if(!m)continue; const kind=m[1],bang=!!m[3]; let scope=m[2]||'general',s=null,perf=false;
 if(bang)s='br'; else if(scope==='internal')continue; else if(kind==='feat')s='feat'; else if(kind==='fix')s='fix'; else if(kind==='perf'){s='feat';perf=true;} else continue;
 if(scope==='deps')scope='dependencies'; let summary=m[4]; summary=summary.charAt(0).toUpperCase()+summary.slice(1); if(summary.endsWith('.'))summary=summary.slice(0,-1); if(perf)summary+=' [perf]';
 const refs=[]; if(kind==='fix')for(const line of r.message.split('\n').slice(1)){const f=/^Fixes #(\d+)$/.exec(line); if(f)refs.push(f[1]);}
 sections[s].push({r,kind,scope,summary,refs,perf}); included.push(r);}
const build=list=>{const map=new Map(); for(const e of list){const k=e.scope+'\u0000'+e.summary; if(!map.has(k))map.set(k,{scope:e.scope,summary:e.summary,items:[]}); map.get(k).items.push(e);} const out=[...map.values()]; for(const g of out){g.items.sort((a,b)=>b.r.t-a.r.t||a.r.idx-b.r.idx); const seen=new Set(); g.refs=[]; for(const it of g.items)for(const n of it.refs)if(!seen.has(n)){seen.add(n);g.refs.push(n);} g.hashes=g.items.map(i=>i.r.hash); g.t=g.items[0].r.t;} out.sort((a,b)=>a.scope<b.scope?-1:a.scope>b.scope?1:b.t-a.t); return out;};
const res={br:build(sections.br),feat:build(sections.feat),fix:build(sections.fix)};
const mask=s=>s.replace(/[0-9a-f]{7,}/g,'H');
for(const k of ['br','feat','fix']) for(const g of res[k]) if(g.items.length>1){ print('GROUP',k,g.scope,g.summary,'refs',JSON.stringify(g.refs)); for(const it of g.items) print('   item t='+new Date(it.r.t).toISOString()+' '+mask(H(it.r.message))+' refs='+JSON.stringify(it.refs)); }
const brFix=res.br.find(g=>g.scope==='general'); print('BR general src:', mask(brFix.items[0].r.message));
// invariants
for(const k of ['br','feat','fix']){const arr=res[k]; for(let i=1;i<arr.length;i++){const a=arr[i-1],b=arr[i]; if(a.scope>b.scope) print('ORDER-FAIL scope',k,a.scope,b.scope); if(a.scope===b.scope&&a.t<b.t) print('ORDER-FAIL time',k,a.scope);} }
print('counts', res.br.length, res.feat.length, res.fix.length, 'included commits', included.length);
print('perf in feat', res.feat.filter(g=>g.summary.includes('[perf]')).length, 'perf commits total', sections.feat.filter(e=>e.perf).length);
print('internal in output', [...res.br,...res.feat,...res.fix].filter(g=>g.scope==='internal').length);
return 'ok';

