const mm=new Map(); for(const line of String(tools.read({path:'.mailmap'})).split('\n').map(l=>l.replace(/^\s*\d+\t/,'')).filter(l=>l.trim()&&!l.startsWith('#'))){const m=/^(.+?) <([^>]+)>(?: <([^>]+)>)?$/.exec(line.trim()); mm.set(m[3]||m[2],m[1].trim());}
const canon=(n,e)=>mm.get(e)||n;
let bad=[], cur=null, prev=null, hashesInFile=[];
for(const l of lines){ if(l.startsWith('## ')){cur=l.slice(3); prev=null; continue;} if(!l.startsWith('- ')||cur==='Contributors') continue;
  const m=/^- \*\*(.+?):\*\* /.exec(l); const scope=m[1]; const hm=/\(([0-9a-f]{7}(?:, [0-9a-f]{7})*)\)$/.exec(l); const hs=hm[1].split(', '); hashesInFile.push(...hs);
  const ts=hs.map(h=>{const r=by7.get(h); if(!r) bad.push('unknown hash'); return Date.parse(r.date);}); const t=Math.max(...ts);
  if(prev){ if(prev.scope>scope) bad.push('scope order '+prev.scope+'>'+scope); if(prev.scope===scope && prev.t<t) bad.push('time order '+scope); }
  prev={scope,t}; }
const includedRows=rows.filter(r=>hashesInFile.includes(r.hash.slice(0,7)));
print('included via file', includedRows.length);
// contributors recomputed
const counts=new Map(), authored=new Set();
for(const r of includedRows){const ppl=new Set(); const an=canon(r.author,r.email); authored.add(an); if(!an.endsWith('[bot]'))ppl.add(an); for(const line of r.message.split('\n').slice(1)){const m=/^Co-authored-by: (.+?) <([^>]+)>$/.exec(line); if(m){const n=canon(m[1].trim(),m[2]); if(!n.endsWith('[bot]'))ppl.add(n);}} for(const p of ppl)counts.set(p,(counts.get(p)||0)+1);}
const exp=[...counts].filter(([n])=>authored.has(n)).sort((a,b)=>b[1]-a[1]||(a[0]<b[0]?-1:a[0]>b[0]?1:0)).map(([n,c])=>'- '+n+' ('+c+')');
const got=lines.slice(lines.indexOf('## Contributors')+2);
print('contrib match', JSON.stringify(exp)===JSON.stringify(got));
// truncated summaries are prefixes
for(const l of lines.filter(x=>x.includes('\u2026'))){ const s=/- \*\*.+?:\*\* (.+?)\u2026/.exec(l)[1]; const cands=includedRows.filter(r=>r.message.split('\n')[0].toLowerCase().includes(s.toLowerCase().replace(/ +/,' ').slice(0,25))); print('trunc len', Array.from(l).length); }
print('bad', JSON.stringify(bad));
return 'done';

